  str_n25_idol_y_concert_fail_desc_2 = "Você não conseguiu ajudar Goldie passar no concerto de avaliação...\nTreine duro e faça melhor da próxima vez!\nCom fãs suficientes ao seu lado, você chegará em pouco tempo!",
