  str_n25_idol_y_lesson_6 = "Illumina Broadcast No. 6: Calistenia",
  str_n25_idol_y_lesson_7 = "Esculturas de gelo e arquitetura de castelos",
  str_n25_idol_y_lesson_8 = "Autotreinamento para Gênios",
  str_n25_idol_y_lesson_9 = "Cozinha bizarra de Roy",
  str_n25_idol_y_lesson_1_desc = "Realizou “Os 300 Versos da Noite Branca”. A luz da lua brilha diante da cidade... Como vai, de novo?",
  str_n25_idol_y_lesson_2_desc = "Realizou \"No. 1 Princess of Rediesel\". Sinsa ficou tão emocionado com a apresentação que chorou...",
  str_n25_idol_y_lesson_3_desc = "Tocou \"A Canção do Correio\". Aposto que cantar isso faz com que as entregas pareçam muito mais rápidas!",
  str_n25_idol_y_lesson_4_desc = "Realizou uma dança de balé. Dançar na ponta dos pés me faz parecer muito mais alta!",
  str_n25_idol_y_lesson_5_desc = "Fez uma demonstração de tiro... Mas será que isso tem mesmo a ver com a dança?",
  str_n25_idol_y_lesson_6_desc = "Realizou Illumina Broadcast Calisthenics No. 6, uma rotina de exercícios. Um dois três quatro! Estique-se para baixo e toque os dedos dos pés!",
  str_n25_idol_y_lesson_7_desc = "Fez uma escultura de gelo em forma de castelo. A neve em cima era feita de glacê de açúcar, então começou a derreter na hora!",
  str_n25_idol_y_lesson_8_desc = "Aprendeu muitas técnicas de performance diferentes com Charon. Ele diz que todos os gênios são solitários!",
  str_n25_idol_y_lesson_9_desc = "Fiz muitas guloseimas do zero... Mas Zeta comeu a maioria enquanto não estávamos olhando!",
  str_n25_idol_y_lesson_2_learn = "Masterizado \"No. 1 Princess of Rediesel\"",
  str_n25_idol_y_lesson_3_learn = "Masterizado \"The Courier's Song\"",
  str_n25_idol_y_lesson_5_learn = "Artes de luta dominadas",
  str_n25_idol_y_lesson_6_learn = "Mastered Illumina Broadcast Calistenia nº 6",
  str_n25_idol_y_lesson_8_learn = "Dominou as 108 habilidades para executar",
  str_n25_idol_y_lesson_9_learn = "Dominou as técnicas de culinária de Roy",
  str_n25_idol_y_activity_title_1 = "Lançar nova música",
  str_n25_idol_y_activity_title_2 = "Lançamento Álbum de Fotos",
  str_n25_idol_y_activity_title_3 = "estrela em um jogo",
  str_n25_idol_y_activity_title_4 = "Gravar um programa de rádio",
  str_n25_idol_y_activity_title_5 = "Encontro de fãs",
  str_n25_idol_y_activity_title_6 = "Fotografe um anúncio de patrocínio",
  str_n25_idol_y_activity_desc_1 = "<color=#6d50c3>Lançado \"Lutumi Owl Lullaby\"</color>\nHoot, hoot ♪ Parece que muitos aurorianos ouvem essa música antes de dormir para ter uma noite de sono melhor.",
  str_n25_idol_y_activity_desc_2 = "<color=#6d50c3>Lançado \"Sky-High Love\"</color>\nAmor no céu, sempre cuidando de você ♪ O Navegador começou a chorar assim que ouviu!",
  str_n25_idol_y_activity_desc_3 = "<color=#6d50c3>Lançamento da \"Sonata do Chef\"</color>\nEles usaram utensílios de cozinha em vez de instrumentos para gravar essa música. Parece que eles até misturaram alguns ruídos do Eclipsite!",
  str_n25_idol_y_activity_desc_4 = "<color=#6d50c3>Álbum de fotos lançado: Fluff and Stuff!</color>\nUma colaboração entre Goldie e Novio com seus coelhos. Os coelhinhos são fofos demais! Quem não gostaria de brincar com essas criaturinhas todos os dias?",
  str_n25_idol_y_activity_desc_5 = "<color=#6d50c3>Álbum de fotos lançado: Bunny Pyjamas</color>\nEste álbum está cheio de fotos de Goldie em seu pijama de coelho favorito! Até os comandantes da Illumina adoram usá-los!",
  str_n25_idol_y_activity_desc_6 = "<color=#6d50c3>Álbum de fotos lançado: Train Hard, Idol!</color>\nEste álbum é composto por fotos tiradas de Goldie durante o treinamento. Cada minuto no palco requer anos de prática! Um verdadeiro ídolo nunca para de treinar!",
  str_n25_idol_y_activity_desc_7 = "<color=#6d50c3>Estrelou em: \"Detetive Golmes\"</color>\nUm grande sucesso estrelando Lilica como Liliarty, o mentor do vilão, e Goldie como Detetive Golmes. O confronto final em Umbraton foi especialmente emocionante!",
  str_n25_idol_y_activity_desc_8 = [[
<color=#6d50c3>Estrelou em: "Fantasma do Teatro"</color>
A estreia de "Phantom of the Theatre" foi um enorme sucesso! Tudo correu bem... Exceto pela parte em que Goldie quebrou um monte de copos cantando em falsete. Acho que todo esse treinamento valeu a pena!]],
  str_n25_idol_y_activity_desc_9 = "<color=#6d50c3>Estrelou em: \"Cinco mil metros por segundo\"</color>\nEsta versão de \"Five Thousand Meters Per Second\" esgotou completamente! Você até conseguiu transformar o palco em um trem, e Charon ele mesmo desempenhou o papel de maestro!",
  str_n25_idol_y_activity_desc_10 = "<color=#6d50c3>Programa de rádio gravado: Idol Legends of Umbraton</color>\nGoldie desempenhou o papel feminino principal em uma transmissão de rádio de Idol Legends of Umbraton. O autor da história não quer ser identificado, mas diz ser um gerente da Guilda Umbraton.",
  str_n25_idol_y_activity_desc_11 = "<color=#6d50c3>Programa de rádio gravado: Ada and the Colossus</color>\nEstrelou uma produção de Ada and the Colossus para uma estação de rádio local. Mesmo sendo bem curta, a história ainda é muito emocionante. Além disso, todas as crianças adoram!",
  str_n25_idol_y_activity_desc_12 = "<color=#6d50c3>Programa de rádio gravado: Gannon City Traffic Report</color>\nAtuou como ator convidado no relatório de tráfego regular de Gannon City. O sistema de transporte subterrâneo da cidade deles é realmente complexo!",
  str_n25_idol_y_activity_desc_13 = "<color=#6d50c3>Organizou um encontro de fãs: Umbraton</color>\nA fila para apertar a mão de sua amada estrela percorreu toda a margem do Gold River!",
  str_n25_idol_y_activity_desc_14 = "<color=#6d50c3>Organizou um encontro de fãs: Rediesel Desert</color>\nFoi uma surpresa ver todos na Rediesel Wrench formar uma fila tão ordenada para o evento! Tudo estava indo muito bem até Barbara pediu um duelo de ídolos.",
  str_n25_idol_y_activity_desc_15 = "<color=#6d50c3>Organizou um encontro de fãs: Illumina</color>\nTodos na Illumina estão tão interessados em ídolos agora! Havia tanta gente no evento... Aparentemente, até o Grande Marechal apareceu disfarçado para conferir!",
  str_n25_idol_y_activity_desc_16 = "<color=#6d50c3>Sessão de fotos concluída: Rediesel Delights</color>\nDepois de tirar fotos promocionais para a Rediesel Delights, uma lanchonete local, a loja de Jomu está lotada há dias!",
  str_n25_idol_y_activity_desc_17 = "<color=#6d50c3>Sessão de fotos concluída: Connolly's Cafe</color>\nMuitas pessoas queriam experimentar o café Connolly's depois que nossas fotos promocionais foram postadas! Na verdade, ela está pensando em contratar baristas em meio período...",
  str_n25_idol_y_activity_desc_18 = "<color=#6d50c3>Sessão de fotos concluída: Northland</color>\nDepois de tirar fotos para promover o turismo de Northland, muitos visitantes viajaram até lá para construir bonecos de neve e aproveitar as vistas!",
  str_n25_idol_y_activity_forwho_1 = "<color=#6d50c3>Lançado \"Lutumi Owl Lullaby\"</color>",
  str_n25_idol_y_activity_forwho_2 = "<color=#6d50c3>Lançado \"Sky-High Love\"</color>",
  str_n25_idol_y_activity_forwho_3 = "<color=#6d50c3>Lançamento da \"Sonata do Chef\"</color>",
  str_n25_idol_y_activity_forwho_4 = "<color=#6d50c3>Álbum de fotos lançado: Fluff and Stuff!</color>",
  str_n25_idol_y_activity_forwho_5 = "<color=#6d50c3>Álbum de fotos lançado: Bunny Pyjamas</color>",
  str_n25_idol_y_activity_forwho_6 = "<color=#6d50c3>Álbum de fotos lançado: Train Hard, Idol!</color>",
  str_n25_idol_y_activity_forwho_7 = "<color=#6d50c3>Estrelou em: \"Detetive Golmes\"</color>",
  str_n25_idol_y_activity_forwho_8 = "<color=#6d50c3>Estrelou em: \"Fantasma do Teatro\"</color>",
  str_n25_idol_y_activity_forwho_9 = "<color=#6d50c3>Estrelou em: \"Cinco mil metros por segundo\"</color>",
  str_n25_idol_y_activity_forwho_10 = "<color=#6d50c3>Programa de rádio gravado: Idol Legends of Umbraton</color>",
  str_n25_idol_y_activity_forwho_11 = "<color=#6d50c3>Programa de rádio gravado: Ada and the Colossus</color>",
  str_n25_idol_y_activity_forwho_12 = "<color=#6d50c3>Programa de rádio gravado: Gannon City Traffic Report</color>",
  str_n25_idol_y_activity_forwho_13 = "<color=#6d50c3>Organizou um encontro de fãs em: Umbraton</color>",
  str_n25_idol_y_activity_forwho_14 = "<color=#6d50c3>Organizou um encontro de fãs em: Rediesel Desert</color>",
  str_n25_idol_y_activity_forwho_15 = "<color=#6d50c3>Organizou um encontro de fãs em: Illumina</color>",
  str_n25_idol_y_activity_forwho_16 = "<color=#6d50c3>Sessão de fotos concluída para: Rediesel Delights</color>",
  str_n25_idol_y_activity_forwho_17 = "<color=#6d50c3>Sessão de fotos concluída para: Connolly's Cafe</color>",
  str_n25_idol_y_activity_forwho_18 = "<color=#6d50c3>Sessão de fotos concluída para: Northland</color>",
  str_n25_idol_y_activity_desc_short_1 = "Hoot, hoot ♪ Parece que muitos aurorianos ouvem essa música antes de dormir para ter uma noite de sono melhor.",
  str_n25_idol_y_activity_desc_short_2 = "Amor acima do céu, sempre cuidando de você ♪ O Navegador começou a chorar assim que ouviu!",
  str_n25_idol_y_activity_desc_short_3 = "Eles usaram utensílios de cozinha em vez de instrumentos para gravar essa música. Parece que eles até misturaram alguns ruídos do Eclipsite!",
  str_n25_idol_y_activity_desc_short_4 = "Uma colaboração entre Goldie e Novio com seus coelhinhos. Os coelhinhos são fofos demais! Quem não gostaria de brincar com essas criaturinhas todos os dias?",
  str_n25_idol_y_activity_desc_short_5 = "Este álbum está cheio de fotos de Goldie em seu pijama de coelho favorito! Até os comandantes da Illumina adoram usá-los!",
  str_n25_idol_y_activity_desc_short_6 = "Este álbum é composto por fotos tiradas de Goldie durante o treinamento. Cada minuto no palco requer anos de prática! Um verdadeiro ídolo nunca para de treinar!",
  str_n25_idol_y_activity_desc_short_7 = "Um sucesso estrondoso estrelado por Lilica como Liliarty, a vilã idealizadora, e Goldie como o detetive Golmes. O confronto final em Umbraton foi uma cena especialmente emocionante!",
  str_n25_idol_y_activity_desc_short_8 = "A estreia de \"Phantom of the Theatre\" foi um enorme sucesso! Tudo correu bem... Exceto pela parte em que Goldie quebrou um monte de copos cantando em falsete. Acho que todo esse treinamento valeu a pena!",
  str_n25_idol_y_activity_desc_short_9 = "Esta versão de \"Five Thousand Meters Per Second\" esgotou completamente! O palco foi transformado em um trem, e Charon ele mesmo desempenhou o papel de maestro!",
  str_n25_idol_y_activity_desc_short_10 = "Goldie desempenhou o papel feminino principal em uma transmissão de rádio de Idol Legends of Umbraton. O autor da história não quer ser identificado, mas diz ser um gerente da Guilda Umbraton.",
  str_n25_idol_y_activity_desc_short_11 = "Estrelou uma produção de \"Ada and the Colossus\" para uma estação de rádio local. Mesmo sendo bem curta, a história ainda é muito emocionante. Além disso, todas as crianças adoram!",
  str_n25_idol_y_activity_desc_short_12 = "Goldie foi um convidado especial no relatório de tráfego regular de Gannon City. O sistema de transporte subterrâneo da cidade deles é realmente complexo!",
  str_n25_idol_y_activity_desc_short_13 = "A fila para apertar a mão de sua amada estrela percorreu toda a margem do Gold River!",
  str_n25_idol_y_activity_desc_short_14 = "Foi uma surpresa ver todos na Rediesel Wrench formar uma fila tão ordenada para o evento! Tudo estava indo muito bem até Barbara pediu um duelo de ídolos.",
  str_n25_idol_y_activity_desc_short_15 = "Todos na Illumina estão tão interessados em ídolos agora! Havia tanta gente no evento... Aparentemente, até o Grande Marechal apareceu disfarçado para conferir!",
  str_n25_idol_y_activity_desc_short_16 = "Depois de tirar as fotos promocionais para uma lanchonete local chamada Rediesel Delights, as pessoas se aglomeraram na loja de Jomu por dias!",
  str_n25_idol_y_activity_desc_short_17 = "Muitas pessoas queriam experimentar o café Connolly's depois que nossas fotos promocionais foram postadas! Na verdade, ela está começando a considerar a contratação de baristas em meio período...",
  str_n25_idol_y_activity_desc_short_18 = "Depois de tirar fotos para promover o turismo em Northland, muitos visitantes viajaram até lá para construir bonecos de neve e aproveitar as vistas!",
  str_n25_idol_y_trun_closed_14 = "O Concerto de Estreia foi um sucesso! The Navigator continua a fazer progressos constantes no caminho para se tornar um produtor.\nMas com o Concerto de Estreia a chegar ao fim, o próximo desafio aproxima-se ainda mais: o Concerto de Avaliação!\nO que o futuro reserva para eles? Volte e continue seu treinamento de ídolo para descobrir!",
  str_n25_idol_y_trun_closed_28 = "O Concurso de Avaliação foi um sucesso! Goldie, Vice, Carleen, e o Navigator reserva um momento para comemorar sua vitória suada.\nAgora só falta o desafio final... o Concerto de Formatura!\nO que o futuro reserva para eles? Volte e continue seu treinamento de ídolo para descobrir!",
  str_n25_idol_y_arrange_desc_1 = "<color=#4c4c4c>Vice</color> quer te encontrar.",
