  str_n25_idol_game_intro_title = "Informações de jogabilidade - Starlit Agency",
  str_n25_idol_game_intro_head_1 = "Treinamento de ídolo",
  str_n25_idol_game_intro_head_2 = "Eventos de ídolos",
  str_n25_idol_game_intro_head_3 = "Concertos",
  str_n25_idol_game_intro_body_1 = "Como produtor, você pode ajudar Goldie melhore como ídolo escolhendo programas de treinamento adequados na interface de treinamento de ídolo.\nDurante o treinamento, você pode encontrar momentos de Inspiração Súbita, que podem aumentar significativamente o progresso de Goldie!\nAlém disso, diferentes aurorianos aparecerão nas várias salas de treinamento de acordo com sua lista de tarefas; fale com eles e veja o que eles têm a oferecer!\nÀs vezes, um paparazzi aparece durante seus treinos; lembre-se de mandá-lo embora com calma e educação!",
  str_n25_idol_game_intro_body_2 = "Organize eventos de ídolos para ganhar mais fãs.\nOs Idol Events têm diferentes requisitos de habilidade, então continue treinando para aumentar seus níveis de habilidade!",
  str_n25_idol_game_intro_body_3 = "Os shows são a melhor maneira de mostrar as habilidades de um ídolo!\nPara sediar um show de sucesso, você precisa ganhar fãs suficientes antes de acontecer, ou então o show falhará!\nOrganize mais eventos de ídolos para aumentar sua base de fãs!",
  str_n25_idol_game_puppy_btn = "Retorno ao Treinamento",
  str_n25_idol_game_puppy_question_name = "Paparazzi",
  str_n25_idol_game_puppy_result_title = "Resultados",
  str_n25_idol_game_puppy_question_1 = "Olá, sou repórter do Daily Drivel. É verdade que a altura relatada por Goldie de 5'6 '' é na verdade uma mentira?",
  str_n25_idol_game_puppy_question_cond_1_1 = "Claro que não! Meça você mesmo, se não acredita em mim!",
  str_n25_idol_game_puppy_question_cond_1_2 = "Goldie realmente tem 5'6 ''!",
  str_n25_idol_game_puppy_question_cond_1_3 = "De qualquer maneira, pelo menos ela é mais alta do que Vic.",
  str_n25_idol_game_puppy_result_1_1 = "Você pega uma fita métrica e mede a altura de Goldie... 5'6'', nem mais nem menos!",
  str_n25_idol_game_puppy_result_1_2 = "O repórter recebe sua resposta pouco convincente e vai embora.\nNo dia seguinte, ele escreve sobre sua falta de provas.\nAlguns fãs de Goldie começam a ter dúvidas sobre ela.",
  str_n25_idol_game_puppy_result_1_3 = "O repórter publica um artigo com uma comparação de altura de Goldie e Vic.\nIniciar, Vic é claramente mais alto que ela.\nO repórter afirma que você estava tentando ridicularizar Vic.\nAlguns fãs de Goldie começam a ter dúvidas sobre ela.",
  str_n25_idol_game_puppy_question_2 = "Olá, sou repórter do Daily Drivel. É verdade que a mais nova música de Goldie foi plagiada de uma música dos Umbraton Boys?",
  str_n25_idol_game_puppy_question_cond_2_1 = "Esses rumores são completamente infundados. Podemos até contratar um especialista para resolver o assunto.",
  str_n25_idol_game_puppy_question_cond_2_2 = "Acho que as músicas não são nada parecidas...",
  str_n25_idol_game_puppy_question_cond_2_3 = "De que garotos Umbraton você está falando? Nunca nem ouvi falar deles!",
  str_n25_idol_game_puppy_result_2_1 = "Você contrata um famoso especialista musical da Umbraton para oferecer sua opinião sobre o assunto.\nApós ampla análise...\nAs duas músicas não têm nenhuma semelhança.",
  str_n25_idol_game_puppy_result_2_2 = "O repórter o acusa de falar por preconceito pessoal.\nAlguns fãs de Goldie começam a ter dúvidas sobre ela.",
  str_n25_idol_game_puppy_result_2_3 = "O repórter o acusa de zombar dos Umbraton Boys.\nAlguns fãs de Goldie começam a ter dúvidas sobre ela.",
  str_n25_idol_game_puppy_question_3 = "Olá, sou repórter do Daily Drivel. Há rumores circulando de que Goldie usa peruca em público e que ela é, de fato, careca. Quer comentar sobre isso?",
  str_n25_idol_game_puppy_question_cond_3_1 = "Vamos pedir a um médico para esclarecer as coisas!",
  str_n25_idol_game_puppy_question_cond_3_2 = "Isso é discriminação contra os carecas e carecas!",
  str_n25_idol_game_puppy_question_cond_3_3 = "Que piada... Por que eu deveria te contar alguma coisa?",
  str_n25_idol_game_puppy_result_3_1 = "Você pede a um médico para avaliar a saúde do couro cabeludo e do cabelo de Goldie.\nO médico garante ao público que o cabelo de Goldie é perfeitamente real e saudável.",
  str_n25_idol_game_puppy_result_3_2 = "Sua resposta só deixa o repórter ainda mais desconfiado.\nMuitos dos fãs de Goldie começaram a se preocupar com a saúde do couro cabeludo.\nAlguns fãs de Goldie começam a ter dúvidas sobre ela.",
  str_n25_idol_game_puppy_result_3_3 = "O repórter acusa você e Goldie de ser arrogante.\nAlguns fãs de Goldie começam a ter dúvidas sobre ela.",
  str_n25_idol_game_puppy_question_4 = "Olá, sou repórter do Daily Drivel. A palavra na rua é que Goldie realmente não sabe cantar e que todas as suas apresentações são dubladas. Isso é verdade?",
  str_n25_idol_game_puppy_question_cond_4_1 = "Por que você não ouve Goldie cantar para si mesmo?",
  str_n25_idol_game_puppy_question_cond_4_2 = "Não podemos nem pagar dubladores profissionais como esses.",
  str_n25_idol_game_puppy_question_cond_4_3 = "O que, esses rumores sem vergonha de novo?",
  str_n25_idol_game_puppy_result_4_1 = "Você pergunta Goldie para cantar \"For Your Ears Only\" para o repórter.",
  str_n25_idol_game_puppy_result_4_2 = "O repórter acusa você de se esquivar da pergunta.\nEle escreve um artigo sobre sua resposta vaga.\nAlguns fãs de Goldie começam a ter dúvidas sobre ela.",
  str_n25_idol_game_puppy_result_4_3 = "O repórter acusa você de caluniar colegas da indústria\ne você não tem nenhuma evidência concreta.\nAlguns fãs de Goldie começam a ter dúvidas sobre ela.",
  str_n25_idol_game_puppy_question_5 = "Olá, sou repórter do Daily Drivel. É verdade que Goldie mantém secretamente um Eclipsite como animal de estimação?",
  str_n25_idol_game_puppy_question_cond_5_1 = "Isso parece ser um mal-entendido. O único animal de estimação de Goldie é seu cachorro.",
  str_n25_idol_game_puppy_question_cond_5_2 = "Se fosse verdade, Goldie pode muito bem engolir o microfone dela na hora!",
  str_n25_idol_game_puppy_question_cond_5_3 = "Por favor, isso é o melhor que você pode inventar?",
  str_n25_idol_game_puppy_result_5_1 = "Você chama Marshmallow,\nque pula alegremente e imediatamente conquista o repórter.",
  str_n25_idol_game_puppy_result_5_2 = "Como o repórter não consegue obter a resposta que procura,\nele decide espalhar um novo boato: Goldie gosta de comer coisas estranhas.\nAlguns fãs de Goldie começam a ter dúvidas sobre ela.",
  str_n25_idol_game_puppy_result_5_3 = "O repórter acusa você de caluniar colegas da indústria\ne você não tem nenhuma evidência concreta.\nAlguns fãs de Goldie começam a ter dúvidas sobre ela.",
  str_n25_idol_game_puppy_question_cond_disable = "O repórter acha que sua resposta é muito vaga,\no que significa que os rumores devem ser verdadeiros.\nAlguns fãs de Goldie começam a ter dúvidas sobre ela.",
  str_n25_idol_game_spine_talk_name = "Goldie",
  str_n25_idol_game_spine_talk_1_1 = "Vamos dar tudo de nós hoje, produtor!",
  str_n25_idol_game_spine_talk_1_2 = "Com PlayerName como meu produtor, posso finalmente focar no meu treinamento!",
  str_n25_idol_game_spine_talk_1_3 = "Que tipo de treinamento faremos hoje?",
  str_n25_idol_game_spine_talk_2_1 = "Espero que o concerto de avaliação corra bem também!",
  str_n25_idol_game_spine_talk_2_2 = "Lá, lá, lá, lá, lá! Eu deveria ir mais alto nessa última nota...! V-você estava ouvindo?!",
  str_n25_idol_game_spine_talk_2_3 = "Você tem feito toneladas de progresso! Isso eu posso atestar!",
  str_n25_idol_game_spine_talk_3_1 = "Vou deixar o plano de treinamento de hoje para você, PlayerName!",
  str_n25_idol_game_spine_talk_3_2 = "A graduação não é o fim, mas um novo começo! Então, vamos fazer o nosso melhor para fazer o maior concerto de formatura de todos os tempos!",
  str_n25_idol_game_spine_talk_3_3 = "Oi! Ho! Vamos! ...Huh? Oh, eu só estou torcendo por você!",
  str_n25_idol_game_spine_talk_concert_1_1 = "O concerto está prestes a começar! Sentindo nervoso?",
  str_n25_idol_game_spine_talk_concert_1_2 = "Relaxar! Com você ao meu lado, tenho certeza que o show vai rolar sem problemas!",
  str_n25_idol_game_spine_talk_concert_1_3 = "Quer acariciar o Marshmallow? Nada acalma os nervos como se aconchegar com uma criatura fofa e peluda!",
  str_n25_idol_game_spine_talk_concert_2_1 = "Meu produtor e eu estamos prontos para o show de avaliação! Vamos fazer isso!",
  str_n25_idol_game_spine_talk_concert_2_2 = "Você não parece mais nem um pouco nervoso, PlayerName! Isso significa que você percorreu um longo caminho, você sabe!",
  str_n25_idol_game_spine_talk_concert_2_3 = "O grampo de cabelo está apontando para baixo! Isso significa que algo bom vai acontecer!",
  str_n25_idol_game_spine_talk_concert_3_1 = "Finalmente chegamos ao concerto de formatura... Eu nunca teria conseguido algo assim sem a sua ajuda, PlayerName!",
  str_n25_idol_game_spine_talk_concert_3_2 = "Acho que ouvi a multidão me chamando para subir no palco! Ouvir tantas pessoas cantando meu nome... não consigo descrever a felicidade que me faz sentir!",
  str_n25_idol_game_spine_talk_concert_3_3 = "Este será o meu maior show de todos os tempos, e devo tudo a você, PlayerName! Agora é hora do meu produtor sentar e me ver brilhar!"
